// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { 
        c = new C(); 
        vm.deal(address(c), 0);
    }

    function testFuzz_property(uint256 amount, uint256 blockTimestamp, uint256 blockNumber) public {
        // Restrict inputs to valid ones for the reference
        amount = bound(amount, 10 ether, 10 ether);
        blockTimestamp = bound(blockTimestamp, 1, type(uint256).max);
        blockNumber = bound(blockNumber, 0, type(uint256).max);

        // Ensure the timestamp increases
        vm.assume(block.timestamp < blockTimestamp);

        // Set block context
        vm.warp(blockTimestamp);
        vm.roll(blockNumber);

        // Send exactly 10 ether via fallback
        vm.deal(address(this), amount);
        (bool success, ) = address(c).call{value: amount}("");

        if (success && block.number % 15 == 0) {
            // The reference contract should have transferred all balance to msg.sender
            assertTrue(address(c).balance == 0);
        } else if (success) {
            // If not divisible by 15, balance should be 10 ether
            assertTrue(address(c).balance == 10 ether);
        }
        // If the call reverted, we don't assert anything
    }
}

